133	    /** Add a claim as {@link #add(String, String, long, BigDecimal, LocalDate, String, String, String)} does, with
134	     *  its tags (comma separated; each trimmed and lower-cased, blanks and repeats dropped). */
135	    @Transactional
136	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
137	            String corrects, String ref, String tags) {
138	        sheets.load(sheetId, user);
139	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
140	        LocalDate today = sheet.getToday();
141	        Person person = people.findByIdAndSheetId(personId, sheetId)
142	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
143	        LocalDate claimDate = date != null ? date : sheet.defaultClaimDate();
144	        int terms = termsOf(sheet, person);
145	        LocalDate dueBy = holidays.dueBy(sheetId, claimDate, terms);
146	        refuseIfClosed(sheetId, dueBy);
147	        refuseIfRetired(person, claimDate);
148	        refuseUnlessCorrects(sheetId, personId, amount, corrects, null);
149	        String reference = refOf(ref);
150	        if (reference != null && claims.existsBySheetIdAndRefIgnoreCase(sheetId, reference)) {
151	            throw refUsed(reference);
152	        }
153	        Rollup.Figures before = rollup.of(sheetId);
154	        Claim claim = new Claim(sheetId, personId, scaled(amount), claimDate, dueBy, noteOf(note), corrects,
155	                claims.lastListed(sheetId) + 1);
156	        claim.setTerms(terms);
157	        boolean late = periods.existsBySheetIdAndSoftClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(
158	                sheetId, dueBy, dueBy);
159	        if (late) {
160	            claim.markLateEntry();
161	        }
162	        claim.setRef(reference);
163	        String tagged = tagsOf(tags);
164	        claim.setTags(tagged);
165	        Claim added = claims.saveAndFlush(claim);
166	        added.logStatus(user, today, shownDue(sheet, added, person));
167	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_ADDED", user, person, added, added.getNumber())
168	                + (reference == null ? "" : " ref=" + reference) + (tagged == null ? "" : " tags=" + tagged));
169	        if (late) {
170	            audit.recordChangeOnCommit(sheetId, user, entry("LATE_ENTRY", user, person, added, null));
171	        }
172	        rollup.recordChanges(sheetId, user, before);
173	        return added;
174	    }
