498	    /** Open a claim's editor for this user, locking the claim for other users until they save or cancel it or the
499	     *  sheet's today changes. Refused for a claim that is not a draft, one due by inside a closed period and one
500	     *  another user has locked; a refused claim takes no lock. Opening it again for the same user keeps the lock. */
501	    @Transactional
502	    public Claim lock(String sheetId, String user, long id) {
503	        sheets.load(sheetId, user);
504	        sheetStore.findLockedById(sheetId).orElseThrow();
505	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
506	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
507	        if (claim.getStatus() != ClaimStatus.DRAFT) {
508	            throw new ResponseStatusException(HttpStatus.CONFLICT,
509	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
510	        }
511	        refuseIfClosed(sheetId, claim.getDueBy());
512	        refuseIfLockedByOther(claim, user);
513	        claim.setLockedBy(user);
