929	    /** Split an amount (more than 0.00 and less than its amount) off an OPEN claim: it keeps the rest and loses any
930	     *  figure a statement bound it to; a new OPEN claim of the same person with the amount split off, the same date
931	     *  and note, no number (it takes one when settled), opened by this user, a due-by fixed now from the terms in force on the sheet's today and
932	     *  naming the original as the claim it was split from, is listed as the person's newest; it is a late entry when
933	     *  the original is, and is numbered within the period of its own due-by. Refused for a claim
934	     *  that is not OPEN or is deferred, one with lines, one due by inside a closed period, an amount out of range, and a role the
935	     *  permission matrix does not allow to open a claim. */
936	    @Transactional
937	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
938	        sheets.load(sheetId, user);
939	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
940	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
941	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
942	        refuseIfClosed(sheetId, claim.getDueBy());
943	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheet.getToday())) {
944	            throw new ResponseStatusException(HttpStatus.CONFLICT,
945	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one not deferred can");
946	        }
947	        if (!sheet.allows("open", roles.roleOf(sheetId, user))) {
948	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
949	        }
950	        if (!claim.getLines().isEmpty()) {
951	            throw new ResponseStatusException(HttpStatus.CONFLICT,
952	                    "A claim with lines has the amount of its lines; it cannot be split");
953	        }
954	        BigDecimal part = scaled(amount);
955	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
956	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
957	                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
958	        }
959	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
960	        Rollup.Figures before = rollup.of(sheetId);
961	        claim.setAmount(claim.getAmount().subtract(part));
962	        claim.unbind();
963	        Claim original = claims.saveAndFlush(claim);
964	        LocalDate date = original.getDate();
965	        int terms = termsOf(sheet, person);
966	        LocalDate dueBy = holidays.dueBy(sheetId, date, terms);
967	        Claim added = new Claim(sheetId, person.getId(), part, date, dueBy, original.getNote(), null,
968	                claims.lastListed(sheetId) + 1);
969	        added.setTerms(terms);
970	        added.openAsSplit(null, user, original.getNumber());
971	        added.setTags(original.getTags());
972	        if (original.isLateEntry()) {
973	            added.markLateEntry();
974	        }
975	        added.logStatus(user, sheet.getToday(), shownDue(sheet, added, person));
976	        added = claims.saveAndFlush(added);
977	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_SPLIT", user, person, original, original.getNumber())
978	                + " into=" + (added.getNumber() == null ? "" : added.getNumber()));
979	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_OPENED", user, person, added, added.getNumber()));
980	        rollup.recordChanges(sheetId, user, before);
981	        return new Split(original, added);
982	    }
