1028	    /** The due a claim would be settled at now: its bound figure, else its live one (raised to the floor in force on
1029	     *  its date), with the late charge it has gained on that figure on top; null when it has no figure. */
1030	    private BigDecimal dueNow(Sheet sheet, Claim claim, Person person) {
1031	        BigDecimal live = liveNow(sheet, claim, person);
1032	        // Settling freezes the claim's figure (its bound one, else its floored live one) with the late charge it has
1033	        // gained on it.
1034	        BigDecimal figure = claim.isBound() ? claim.getBoundDue() : live;
1035	        return figure == null ? null : figure.add(lateCharge(claim, figure, sheet, person.gradeOn(claim.getDate())));
1036	    }
