1038	    /** The due a claim would have been settled at as it stood at the end of a date, that date standing in for the
1039	     *  sheet's today, as the as-of view works it out: the sheet, its rates, the claim's person and its claims as they
1040	     *  stood then (see {@link SheetHistory}), its bound figure, else its live one raised to the floor in force then,
1041	     *  with the late charge it had gained on that figure by then on top; null when it had no figure. Refused for a date after the
1042	     *  sheet's today and for a claim not on the sheet by then. */
1043	    private BigDecimal dueAsOf(Sheet sheet, Claim claim, LocalDate on) {
1044	        String sheetId = sheet.getId();
1045	        if (on.isAfter(sheet.getToday())) {
1046	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
1047	                    "A claim can be settled as of a date on or before " + sheet.getToday());
1048	        }
1049	        SheetState then = history.asOf(sheetId, on).orElse(null);
1050	        Claim claimThen = then == null ? null : then.rebuildClaims(sheetId).stream()
1051	                .filter(c -> c.getId().equals(claim.getId())).findFirst().orElse(null);
1052	        SheetState.PersonState personState = claimThen == null ? null
1053	                : then.person(claimThen.getPersonId()).orElse(null);
1054	        if (personState == null) {
1055	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim was not on the sheet by " + on);
1056	        }
1057	        Sheet sheetThen = then.rebuildSheet(sheet, on);
1058	        Person personThen = personState.rebuild(sheetId);
1059	        List<Claim> claimsThen = then.rebuildClaims(sheetId);
1060	        if (claimThen.getSettledDue() != null) {
1061	            return claimThen.getSettledDue();
1062	        }
1063	        String grade = personThen.gradeOn(claimThen.getDate());
1064	        BigDecimal figure = claimThen.isBound() ? claimThen.getBoundDue()
1065	                : history.ratesOf(sheetId, then, on).inForceOn(grade, claimThen.getDate(), claimThen.getId())
1066	                        .map(Rate::getRate)
1067	                        .map(rate -> floored(claimThen, liveFigure(claimThen, rate,
1068	                                sheetThen.roundingFor(roundingDate(claimThen, claimsThen))), sheetThen))
1069	                        .orElse(null);
1070	        return figure == null ? null : figure.add(lateCharge(claimThen, figure, sheetThen, grade));
1071	    }
