1077	        String sheetId = sheet.getId();
1078	        return rates.of(sheetId).inForceOn(person.gradeOn(claim.getDate()), claim.getDate(), claim.getId())
1079	                .map(Rate::getRate)
1080	                .map(rate -> floored(claim, liveFigure(claim, rate, sheet.roundingFor(roundingDate(claim,
1081	                        claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, claim.getPersonId())))), sheet))
1082	                .orElse(null);
1083	    }
