1110	    /** The next number for a claim due by this day, opened now: within its period (<period name>-<n>, or X-<n>
1111	     *  in no period) while the sheet's period numbering is on by its today, else the next number in the sheet-wide
1112	     *  sequence its tree shares within the fiscal year of the day (FY<year>-<n>, counting from 1 each year). */
1113	    private String nextNumber(Sheet sheet, LocalDate date) {
1114	        if (!sheet.numbersPerPeriod()) {
1115	            int year = sheet.fiscalYearOf(date);
1116	            int last = lastNumberInTree(sheet, year);
1117	            ClaimFiscalSequence sequence = fiscalSequences.findBySheetIdAndFiscalYear(sheet.getId(), year)
1118	                    .orElseGet(() -> new ClaimFiscalSequence(sheet.getId(), year));
1119	            String number = sequence.nextAfter(last);
1120	            fiscalSequences.save(sequence);
1121	            return number;
1122	        }
1123	        String prefix = prefixOn(sheet, date);
1124	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(sheet.getId(), prefix)
1125	                .orElseGet(() -> new ClaimSequence(sheet.getId(), prefix));
1126	        String number = sequence.next();
1127	        sequences.save(sequence);
1128	        return number;
1129	    }
