1131	    /** The last sheet-wide number given in a fiscal year anywhere in the sheet's tree but the sheet itself: the
1132	     *  sheet at the top of its line of parents and all of that sheet's descendants. The top sheet is locked so the
1133	     *  tree's numbers are given one at a time. */
1134	    private int lastNumberInTree(Sheet sheet, int fiscalYear) {
1135	        List<String> ancestors = sheetStore.ancestorsOf(sheet.getId(), Integer.MAX_VALUE);
1136	        String top = ancestors.isEmpty() ? sheet.getId() : ancestors.get(ancestors.size() - 1);
1137	        if (!top.equals(sheet.getId())) {
1138	            sheetStore.findLockedById(top);
1139	        }
1140	        Set<String> others = new HashSet<>(sheetStore.descendantsOf(top));
1141	        others.add(top);
1142	        others.remove(sheet.getId());
1143	        return others.isEmpty() ? 0 : fiscalSequences.lastNumberOf(others, fiscalYear);
1144	    }
