1146	    /** The prefix of the numbers given within the period a day is in: its name, or X in no period. */
1147	    private String prefixOn(Sheet sheet, LocalDate date) {
1148	        return periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
1149	                .filter(p -> p.contains(date)).map(Period::getName).findFirst().orElse(NO_PERIOD);
1150	    }
