1152	    /** Refuse to settle or approve a claim whose due is above the proof threshold in force on its date for its
1153	     *  person's grade then while it has no proofs, or, while the sheet sets proof kinds, no proof of one of them (a
1154	     *  claim with no due, or with no threshold then, needs none). */
1155	    private static void refuseUnproven(Sheet sheet, Claim claim, Person person, BigDecimal due) {
1156	        BigDecimal threshold = sheet.proofThresholdFor(person.gradeOn(claim.getDate()), claim.getDate());
1157	        if (threshold == null || due == null || due.compareTo(threshold) <= 0) {
1158	            return;
1159	        }
