1357	    /** The late charge a claim would have gained on its figure by the sheet's today were it still open. */
1358	    private static BigDecimal lateChargeAsOpen(Claim claim, BigDecimal figure, Sheet sheet, String grade) {
1359	        BigDecimal none = BigDecimal.ZERO.setScale(2);
1360	        if (figure == null || claim.isCorrection() || claim.isWaived()) {
1361	            return none;
1362	        }
1363	        LocalDate from = overdueFrom(claim, sheet, grade);
1364	        long periods = ChronoUnit.DAYS.between(from, sheet.getToday()) / 30;
1365	        RoundingMode rounding = sheet.roundingFor(claim.getDate());
1366	        BigDecimal charge = none;
1367	        for (long k = 1; k <= periods; k++) {
1368	            charge = charge.add(dueOn(figure.add(charge), sheet.latePctOn(from.plusDays(30 * k)), rounding));
1369	        }
1370	        return charge;
1371	    }
