42	public class Rollup {
43	
44	    /** A person's figures: claimed, due-total and overdue-total, each with two decimals; due-total is "n/a" when they
45	     *  have none; and, as the screen shows them, their settled-total and open-total (their due-total before the cap
46	     *  split by status: the dues of their SETTLED claims that count, and of their OPEN and PENDING ones, with the parts
47	     *  they hold of others' claims, none counting as 0) and their cut total, each with two decimals. */
48	    public record PersonFigures(String name, String claimed, String dueTotal, String overdueTotal,
49	            String settledTotal, String openTotal, String cutTotal) {
50	    }
51	
52	    /** A part a person holds of another person's claim. */
53	    private record HeldPart(Claim claim, BigDecimal part) {
54	    }
55	
56	    /** A sheet's figures: each person's, by id in the order they were added, and the sheet's totals. */
57	    public record Figures(Map<Long, PersonFigures> people, String claimedTotal, String dueTotal, String overdueTotal) {
58	    }
59	
60	    private static final String NOT_AVAILABLE = "n/a";
61	
62	    private final SheetRepository sheets;
63	    private final PersonRepository people;
64	    private final ClaimRepository claims;
65	    private final RateChains rates;
66	    private final PeriodRepository periods;
67	    private final Audit audit;
68	    private final PoolService pools;
69	
70	    public Rollup(SheetRepository sheets, PersonRepository people, ClaimRepository claims, RateChains rates,
71	            PeriodRepository periods, Audit audit, @Lazy PoolService pools) {
72	        this.pools = pools;
73	        this.periods = periods;
74	        this.sheets = sheets;
75	        this.people = people;
76	        this.claims = claims;
77	        this.rates = rates;
78	        this.audit = audit;
79	    }
80	
81	    /** The sheet's figures as the store holds them now. */
82	    public Figures of(String sheetId) {
83	        return of(sheets.findById(sheetId).orElse(null), rates.of(sheetId),
84	                people.findBySheetIdOrderByPositionAscIdAsc(sheetId), claims.findBySheetIdOrderByListedDescIdDesc(sheetId));
85	    }
86	
87	    /** The figures of a sheet holding these rates, people (in list order) and claims (in list order), worked out on
88	     *  its today: the live sheet's, with each person's cut total as it stands now (none: no sheet). */
89	    public Figures of(Sheet sheet, RateChain sheetRates, List<Person> sheetPeople, List<Claim> sheetClaims) {
90	        return of(sheet, sheetRates, sheetPeople, sheetClaims,
91	                sheet == null ? Map.of() : pools.cutTotals(sheet.getId(), null));
92	    }
93	
94	    /** The sheet's figures as the store holds them now, worked out as a screen previewing a date reads them (null:
95	     *  none), that date standing in for its today. */
96	    public Figures previewed(String sheetId, LocalDate preview) {
97	        return previewed(sheets.findById(sheetId).orElse(null), rates.of(sheetId),
98	                people.findBySheetIdOrderByPositionAscIdAsc(sheetId), claims.findBySheetIdOrderByListedDescIdDesc(sheetId),
99	                preview);
100	    }
101	
102	    /** The figures of the live sheet as {@link #of(Sheet, RateChain, List, List)}, worked out as a screen previewing a
103	     *  date reads them (null: none): over its current records, that date standing in for its today. */
104	    public Figures previewed(Sheet sheet, RateChain sheetRates, List<Person> sheetPeople, List<Claim> sheetClaims,
105	            LocalDate preview) {
106	        if (sheet == null || preview == null) {
107	            return of(sheet, sheetRates, sheetPeople, sheetClaims);
108	        }
109	        return of(Preview.of(sheet, preview), sheetRates, sheetPeople, sheetClaims,
110	                pools.cutTotals(sheet.getId(), null, preview));
111	    }
112	
113	    /** The figures of a sheet as {@link #of(Sheet, RateChain, List, List)}, with these cut totals by person id (a
114	     *  person left out has none): the live sheet's, or one rebuilt as it stood at a moment (none: no sheet). */
115	    public Figures of(Sheet sheet, RateChain sheetRates, List<Person> sheetPeople, List<Claim> sheetClaims,
116	            Map<Long, BigDecimal> cutTotals) {
117	        LocalDate today = sheet == null ? null : sheet.getToday();
118	        Map<Long, PersonFigures> byPerson = new LinkedHashMap<>();
119	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
120	        List<BigDecimal> dueFigures = new ArrayList<>();
121	        List<BigDecimal> overdueFigures = new ArrayList<>();
122	        Map<Long, Person> ownerOf = new LinkedHashMap<>();
123	        sheetPeople.forEach(p -> ownerOf.put(p.getId(), p));
124	        for (Person person : sheetPeople) {
125	            List<Claim> counting = sheetClaims.stream()
126	                    .filter(c -> c.getPersonId().equals(person.getId()) && person.counts(c, today)
127	                            && !c.isDeferredOn(today))
128	                    .toList();
129	            // Claimed leaves out corrections: claims that correct another; a held claim still counts in it.
130	            BigDecimal claimed = sheetClaims.stream()
131	                    .filter(c -> c.getPersonId().equals(person.getId()) && person.countsClaimed(c, today)
132	                            && !c.isDeferredOn(today) && c.getCorrects() == null)
133	                    .map(Claim::getAmount)
134	                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
135	            claimedTotal = claimedTotal.add(claimed);
136	            // As on screen: with no rate in force today for their grade on the sheet's today, nor for the grade
137	            // any of their claims is at, and no claim that has a due, the person has no due-total.
138	            // A shared claim's own person counts its due less its holders' parts; each holder counts their part.
139	            List<HeldPart> ownParts = Stream.concat(counting.stream()
140	                    .map(c -> {
141	                        BigDecimal claimDue = dueOf(c, person.gradeOn(c.getDate()), sheetRates, sheet, sheetClaims);
142	                        return claimDue == null ? null : new HeldPart(c,
143	                                claimDue.subtract(sharedPartOf(c, claimDue, ownerOf::get, sheetRates, sheet, sheetClaims)));
144	                    }), heldPartsOf(person, ownerOf, today, sheetRates, sheet, sheetClaims).stream())
145	                    .filter(Objects::nonNull)
146	                    .toList();
147	            List<BigDecimal> dues = ownParts.stream().map(HeldPart::part).toList();
148	            BigDecimal settled = ownParts.stream().filter(h -> h.claim().getStatus() == ClaimStatus.SETTLED)
149	                    .map(HeldPart::part).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
150	            BigDecimal open = ownParts.stream().filter(h -> h.claim().getStatus() == ClaimStatus.OPEN
151	                            || h.claim().getStatus() == ClaimStatus.PENDING)
152	                    .map(HeldPart::part).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
153	            BigDecimal cut = cutTotals.getOrDefault(person.getId(), BigDecimal.ZERO).setScale(2);
154	            boolean anyRate = today != null && Stream.concat(Stream.of(person.gradeOn(today)),
155	                            counting.stream().map(c -> person.gradeOn(c.getDate())))
156	                    .anyMatch(grade -> sheetRates.inForceOn(grade, today).isPresent());
157	            String due = NOT_AVAILABLE;
158	            if (!dues.isEmpty() || anyRate) {
159	                BigDecimal sum = dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
160	                BigDecimal total = sheet == null ? sum : sheet.capped(sum,
161	                        cutTotals.getOrDefault(person.getId(), BigDecimal.ZERO.setScale(2)),
162	                        counting.stream().map(Claim::getDate).max(Comparator.naturalOrder()).orElse(null));
163	                dueFigures.add(total);
164	                due = total.toPlainString();
165	            }
166	            // As on screen: the dues of the claims that count which are open and due by (plus their grade's grace
167	            // days) a day before the sheet's today.
168	            BigDecimal overdue = counting.stream()
169	                    .filter(c -> today != null && ClaimService.isOverdue(c, sheet, person.gradeOn(c.getDate())))
170	                    .map(c -> dueOf(c, person.gradeOn(c.getDate()), sheetRates, sheet, sheetClaims))
171	                    .filter(Objects::nonNull)
172	                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
173	            overdueFigures.add(overdue);
174	            byPerson.put(person.getId(),
175	                    new PersonFigures(person.getName(), claimed.toPlainString(), due, overdue.toPlainString(),
176	                            settled.toPlainString(), open.toPlainString(), cut.toPlainString()));
177	        }
178	        return new Figures(byPerson, claimedTotal.toPlainString(), trimmedSum(dueFigures).toPlainString(),
179	                trimmedSum(overdueFigures).toPlainString());
180	    }
181	
182	    /** The parts a person holds of the live sheet's other people's claims that count on its today, as
183	     *  {@link #heldParts}: what their due-total adds for the claims shared with them. */
184	    public List<BigDecimal> heldParts(Sheet sheet, RateChain sheetRates, Person person) {
185	        List<Person> sheetPeople = people.findBySheetIdOrderByPositionAscIdAsc(sheet.getId());
186	        Map<Long, Person> ownerOf = new LinkedHashMap<>();
187	        sheetPeople.forEach(p -> ownerOf.put(p.getId(), p));
188	        return heldParts(person, ownerOf, sheet.getToday(), sheetRates, sheet,
189	                claims.findBySheetIdOrderByListedDescIdDesc(sheet.getId()));
190	    }
191	
192	    /** The parts a person holds of other people's claims that count (as for their own person), each as
193	     *  {@link #partOf}; a claim with no due adds none, nor does one whose part the person's grade has no rate for. */
194	    private static List<BigDecimal> heldParts(Person person, Map<Long, Person> ownerOf, LocalDate today,
195	            RateChain sheetRates, Sheet sheet, List<Claim> sheetClaims) {
196	        return heldPartsOf(person, ownerOf, today, sheetRates, sheet, sheetClaims).stream().map(HeldPart::part).toList();
197	    }
198	
199	    /** The parts as {@link #heldParts}, each with the claim it is a part of. */
200	    private static List<HeldPart> heldPartsOf(Person person, Map<Long, Person> ownerOf, LocalDate today,
201	            RateChain sheetRates, Sheet sheet, List<Claim> sheetClaims) {
202	        List<HeldPart> parts = new ArrayList<>();
203	        for (Claim claim : sheetClaims) {
204	            ClaimShare share = claim.shareOf(person.getId());
205	            Person owner = ownerOf.get(claim.getPersonId());
206	            if (share == null || owner == null || !owner.counts(claim, today) || claim.isDeferredOn(today)) {
207	                continue;
208	            }
209	            BigDecimal due = dueOf(claim, owner.gradeOn(claim.getDate()), sheetRates, sheet, sheetClaims);
210	            BigDecimal part = due == null ? null : partOf(claim, share, due, person, sheetRates, sheet, sheetClaims);
211	            if (part != null) {
212	                parts.add(new HeldPart(claim, part));
213	            }
214	        }
215	        return parts;
216	    }
217	
218	    /** The parts of a claim's due its holders hold, added up, each as {@link #partOf} (one with no rate adding
219	     *  0.00); the holders are found by person id. */
220	    public static BigDecimal sharedPartOf(Claim claim, BigDecimal due, Function<Long, Person> holders,
221	            RateChain sheetRates, Sheet sheet, Collection<Claim> roundingClaims) {
222	        BigDecimal total = BigDecimal.ZERO.setScale(2);
223	        for (ClaimShare share : claim.getShares()) {
224	            Person holder = holders.apply(share.getPersonId());
225	            BigDecimal part = holder == null ? null
226	                    : partOf(claim, share, due, holder, sheetRates, sheet, roundingClaims);
227	            total = part == null ? total : total.add(part);
228	        }
229	        return total;
230	    }
231	
232	    /** A holder's part of a claim with this due: a settled claim keeps its parts frozen, its settled due times the
233	     *  holder's share divided by 100, rounded half to even; any other claim's is its amount times the holder's share
234	     *  divided by 100, times the rate of the holder's own grade in force on the claim's date divided by 100, rounded
235	     *  as the claim rounds; null when their grade has no rate then. */
236	    public static BigDecimal partOf(Claim claim, ClaimShare share, BigDecimal due, Person holder,
237	            RateChain sheetRates, Sheet sheet, Collection<Claim> roundingClaims) {
238	        if (claim.getSettledDue() != null) {
239	            return share.partOf(due);
240	        }
241	        RoundingMode rounding = sheet == null ? RoundingMode.HALF_EVEN
242	                : sheet.roundingFor(ClaimService.roundingDate(claim, roundingClaims));
243	        return sheetRates.inForceOn(holder.gradeOn(claim.getDate()), claim.getDate(), claim.getId())
244	                .map(rate -> share.partOf(claim.getAmount(), rate.getRate(), rounding))
245	                .orElse(null);
246	    }
247	
248	    /** A person's score, as the screen shows it. */
249	    public record PersonScore(String name, long score) {
250	    }
251	
252	    /** Each person's score on the sheet's today as the store holds it now, by id in list order, as the screen shows
253	     *  it: the dues of their SETTLED claims that count and correct nothing, less 500.00 for each of their overdue claims that count,
254	     *  divided by 100 and rounded half to even to a whole number. */
255	    public Map<Long, PersonScore> scoresOf(String sheetId) {
256	        Sheet sheet = sheets.findById(sheetId).orElse(null);
257	        LocalDate today = sheet == null ? null : sheet.getToday();
258	        RateChain sheetRates = rates.of(sheetId);
259	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
260	        Map<Long, PersonScore> byPerson = new LinkedHashMap<>();
261	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
262	            List<Claim> counting = sheetClaims.stream()
263	                    .filter(c -> c.getPersonId().equals(person.getId()) && person.counts(c, today)
264	                            && !c.isDeferredOn(today))
265	                    .toList();
266	            BigDecimal settled = counting.stream()
267	                    .filter(c -> c.getStatus() == ClaimStatus.SETTLED && c.getCorrects() == null)
268	                    .map(c -> dueOf(c, person.gradeOn(c.getDate()), sheetRates, sheet, sheetClaims))
269	                    .filter(Objects::nonNull)
270	                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
271	            long overdue = counting.stream()
272	                    .filter(c -> today != null && ClaimService.isOverdue(c, sheet, person.gradeOn(c.getDate())))
273	                    .count();
274	            BigDecimal score = settled.subtract(BigDecimal.valueOf(500 * overdue))
275	                    .divide(BigDecimal.valueOf(100))
276	                    .setScale(0, RoundingMode.HALF_EVEN);
277	            byPerson.put(person.getId(), new PersonScore(person.getName(), score.longValueExact()));
278	        }
279	        return byPerson;
280	    }
281	
282	    /** The dues of the sheet's claims that count on its today (as for their person's due-total, not deferred), added
283	     *  up by the policy version in force on each claim's date (0: before the first); a claim with no due adds none. */
284	    public Map<Integer, BigDecimal> dueByPolicyVersion(Sheet sheet) {
285	        RateChain sheetRates = rates.of(sheet.getId());
286	        LocalDate today = sheet.getToday();
287	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheet.getId());
288	        Map<Integer, BigDecimal> dues = new LinkedHashMap<>();
289	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheet.getId())) {
290	            for (Claim claim : sheetClaims) {
291	                if (!claim.getPersonId().equals(person.getId()) || !person.counts(claim, today)
292	                        || claim.isDeferredOn(today)) {
293	                    continue;
294	                }
295	                BigDecimal due = dueOf(claim, person.gradeOn(claim.getDate()), sheetRates, sheet, sheetClaims);
296	                if (due != null) {
297	                    dues.merge(sheet.policyVersionOn(claim.getDate()), due, BigDecimal::add);
298	                }
299	            }
300	        }
301	        return dues;
302	    }
303	
304	    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
305	    public static BigDecimal trimmedSum(List<BigDecimal> figures) {
306	        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
307	        if (figures.size() < 3) {
308	            return sum;
309	        }
310	        BigDecimal highest = figures.stream().max(BigDecimal::compareTo).orElseThrow();
311	        BigDecimal lowest = figures.stream().min(BigDecimal::compareTo).orElseThrow();
312	        return sum.subtract(highest).subtract(lowest);
313	    }
314	
315	    /** Each person's due-total for the dates from {@code from} to {@code to} inclusive, by person id, as the screen
316	     *  shows a person's period figure: the dues as shown now of their claims that counted by the status they had at the end
317	     *  of {@code to} (a held person's open ones dated within a
318	     *  hold and not stated do not) due by in it, none counting as 0; every person on the sheet has one. */
319	    public Map<Long, BigDecimal> dueByPersonBetween(String sheetId, LocalDate from, LocalDate to) {
320	        RateChain sheetRates = rates.of(sheetId);
321	        Sheet sheet = sheets.findById(sheetId).orElse(null);
322	        LocalDate today = sheet == null ? null : sheet.getToday();
323	        Map<Long, Person> personOf = new LinkedHashMap<>();
324	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
325	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
326	            personOf.put(p.getId(), p);
327	            totals.put(p.getId(), BigDecimal.ZERO.setScale(2));
328	        });
329	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
330	        for (Claim claim : sheetClaims) {
331	            Person person = personOf.get(claim.getPersonId());
332	            if (person == null || !person.countsAtEnd(claim, to, today) || claim.isDeferredOn(today) || claim.getDueBy().isBefore(from) || claim.getDueBy().isAfter(to)) {
333	                continue;
334	            }
335	            BigDecimal due = dueOf(claim, person.gradeOn(claim.getDate()), sheetRates, sheet, sheetClaims);
336	            if (due != null) {
337	                totals.merge(person.getId(), due, BigDecimal::add);
338	            }
339	        }
340	        return totals;
341	    }
342	
343	    /** Each person's carried figure for a period, by person id, as the screen shows it: the dues as shown now of
344	     *  their claims that count (as for the period's figures) which are due by in a period of the sheet ending before
345	     *  this one starts and were still OPEN or PENDING at the end of this period's last day, none counting as 0, plus
346	     *  their opening balance for it; every person on the sheet has one. */
347	    public Map<Long, BigDecimal> carriedByPerson(String sheetId, Period period) {
348	        RateChain sheetRates = rates.of(sheetId);
349	        Sheet sheet = sheets.findById(sheetId).orElse(null);
350	        LocalDate today = sheet == null ? null : sheet.getToday();
351	        LocalDate end = period.getToDate();
352	        List<Period> sheetPeriods = periods.findBySheetIdOrderByFromDateAsc(sheetId);
353	        Map<Long, Person> personOf = new LinkedHashMap<>();
354	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
355	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
356	            personOf.put(p.getId(), p);
357	            totals.put(p.getId(), period.openingOf(p.getId()));
358	        });
359	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
360	        for (Claim claim : sheetClaims) {
361	            Person person = personOf.get(claim.getPersonId());
362	            if (person == null || !person.countsAtEnd(claim, end, today) || claim.isDeferredOn(today)) {
363	                continue;
364	            }
365	            ClaimStatus status = claim.statusAt(end);
366	            if (status != ClaimStatus.OPEN && status != ClaimStatus.PENDING) {
367	                continue;
368	            }
369	            boolean earlier = sheetPeriods.stream().filter(p -> p.contains(claim.getDueBy())).findFirst()
370	                    .map(own -> own.getToDate().isBefore(period.getFromDate())).orElse(false);
371	            if (!earlier) {
372	                continue;
373	            }
374	            BigDecimal due = dueOf(claim, person.gradeOn(claim.getDate()), sheetRates, sheet, sheetClaims);
375	            if (due != null) {
376	                totals.merge(person.getId(), due, BigDecimal::add);
377	            }
378	        }
379	        return totals;
380	    }
381	
382	    /** Each person's open figure at {@code end}, by person id: the dues as shown now of their claims that count (as for
383	     *  the period's figures) which are due by in one of {@code yearPeriods} and were still OPEN or PENDING at the end
384	     *  of {@code end}, none counting as 0; every person on the sheet has one. */
385	    public Map<Long, BigDecimal> openByPersonAt(String sheetId, List<Period> yearPeriods, LocalDate end) {
386	        RateChain sheetRates = rates.of(sheetId);
387	        Sheet sheet = sheets.findById(sheetId).orElse(null);
388	        LocalDate today = sheet == null ? null : sheet.getToday();
389	        Map<Long, Person> personOf = new LinkedHashMap<>();
390	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
391	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
392	            personOf.put(p.getId(), p);
393	            totals.put(p.getId(), BigDecimal.ZERO.setScale(2));
394	        });
395	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
396	        for (Claim claim : sheetClaims) {
397	            Person person = personOf.get(claim.getPersonId());
398	            if (person == null || !person.countsAtEnd(claim, end, today) || claim.isDeferredOn(today)) {
399	                continue;
400	            }
401	            ClaimStatus status = claim.statusAt(end);
402	            if (status != ClaimStatus.OPEN && status != ClaimStatus.PENDING) {
403	                continue;
404	            }
405	            if (yearPeriods.stream().noneMatch(p -> p.contains(claim.getDueBy()))) {
406	                continue;
407	            }
408	            BigDecimal due = dueOf(claim, person.gradeOn(claim.getDate()), sheetRates, sheet, sheetClaims);
409	            if (due != null) {
410	                totals.merge(person.getId(), due, BigDecimal::add);
411	            }
412	        }
413	        return totals;
414	    }
415	
416	    /** What a candidate rate would change: how many claims would show a different due, and the sum of the
417	     *  differences (new due minus current due), with two decimals. */
418	    public record RatePreview(int count, String diff) {
419	    }
420	
421	    /** How the OPEN and PENDING claims of people on a grade (in force on each claim's date) would change were a rate
422	     *  to apply to that grade on every date: a claim bound by a statement does not change and a settled one is not
423	     *  counted; a due of none counts as 0 in the sum. Nothing is stored. */
424	    public RatePreview preview(String sheetId, String grade, BigDecimal rate) {
425	        RateChain sheetRates = rates.of(sheetId);
426	        RateChain candidate = sheetRates.withOwn(Stream.concat(
427	                sheetRates.levels().get(0).stream().filter(r -> !r.getGrade().equals(grade)),
428	                Stream.of(new Rate(sheetId, grade, null, rate.setScale(2, RoundingMode.UNNECESSARY)))).toList());
429	        Sheet sheet = sheets.findById(sheetId).orElse(null);
430	        Map<Long, Person> personOf = new LinkedHashMap<>();
431	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> personOf.put(p.getId(), p));
432	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
433	        int count = 0;
434	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
435	        for (Claim claim : sheetClaims) {
436	            Person person = personOf.get(claim.getPersonId());
437	            if (person == null || claim.getSettledDue() != null
438	                    || (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING)
439	                    || !grade.equals(person.gradeOn(claim.getDate()))) {
440	                continue;
441	            }
442	            BigDecimal now = dueOf(claim, grade, sheetRates, sheet, sheetClaims);
443	            BigDecimal then = dueOf(claim, grade, candidate, sheet, sheetClaims);
444	            if (!Objects.equals(now, then)) {
445	                count++;
446	                diff = diff.add(then == null ? BigDecimal.ZERO : then)
447	                        .subtract(now == null ? BigDecimal.ZERO : now);
448	            }
449	        }
450	        return new RatePreview(count, diff.setScale(2).toPlainString());
451	    }
452	
453	    /**
454	     * Record, once the change commits, how the sheet's figures moved since {@code before}: a ROLLUP line
455	     * for each person whose figures changed (one who did not exist before counting as changed), then a
456	     * TOTALS line if the sheet's totals changed, then the ALERT lines of the people who crossed the sheet's alert
457	     * threshold (see {@link #recordAlerts}). Nothing is recorded when no figure moved.
458	     */
459	    public void recordChanges(String sheetId, String user, Figures before) {
460	        Figures after = of(sheetId);
461	        after.people().forEach((id, figures) -> {
462	            PersonFigures was = before.people().get(id);
463	            if (was == null || !was.claimed().equals(figures.claimed()) || !was.dueTotal().equals(figures.dueTotal())
464	                    || !was.overdueTotal().equals(figures.overdueTotal())) {
465	                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
466	                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal()
467	                        + " overdue-total=" + figures.overdueTotal());
468	            }
469	        });
470	        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
471	                || !before.overdueTotal().equals(after.overdueTotal())) {
472	            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
473	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
474	        }
475	        recordAlerts(sheetId, user, before, after);
476	    }
477	
478	    /**
479	     * Record, once the change commits, an ALERT line, in list order, for each person whose due-total went from at or
480	     * below the sheet's alert threshold (or none, or not being on the sheet) to above it between {@code before} (null:
481	     * nobody was) and {@code after}. Nothing is recorded while the threshold is off.
482	     */
483	    public void recordAlerts(String sheetId, String user, Figures before, Figures after) {
484	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
485	        if (threshold == null) {
486	            return;
487	        }
488	        after.people().forEach((id, figures) -> {
489	            PersonFigures was = before == null ? null : before.people().get(id);
490	            if (above(figures, threshold) && (was == null || !above(was, threshold))) {
491	                audit.recordOnCommit("ALERT sheet=" + sheetId + " by=" + user + " name=" + figures.name()
492	                        + " due-total=" + figures.dueTotal());
493	            }
494	        });
495	    }
496	
497	    private static boolean above(PersonFigures figures, BigDecimal threshold) {
498	        return !NOT_AVAILABLE.equals(figures.dueTotal()) && new BigDecimal(figures.dueTotal()).compareTo(threshold) > 0;
499	    }
500	
501	    /** A claim's due: its settled figure, else its stated one, else its amount at the rate in force on its date of
502	     *  its person's grade in force on that date (the sheet's own, else its nearest ancestor's), rounded as the claim rounds (by the sheet's policy date) and raised to the floor in force on its date unless it is a
503	     *  correction; an overdue claim's late charge, worked out on that figure, is added on top of it. */
504	    private static BigDecimal dueOf(Claim claim, String grade, RateChain sheetRates, Sheet sheet, List<Claim> sheetClaims) {
505	        if (claim.getSettledDue() != null) {
506	            return claim.getSettledDue();
507	        }
508	        RoundingMode rounding = sheet == null ? RoundingMode.HALF_EVEN
509	                : sheet.roundingFor(ClaimService.roundingDate(claim, sheetClaims));
510	        BigDecimal figure = claim.isBound() ? claim.getBoundDue()
511	                : sheetRates.inForceOn(grade, claim.getDate(), claim.getId())
512	                        .map(rate -> ClaimService.floored(claim, ClaimService.liveFigure(claim, rate.getRate(), rounding), sheet))
513	                        .orElse(null);
514	        return figure == null || sheet == null ? figure
515	                : figure.add(ClaimService.lateCharge(claim, figure, sheet, grade));
516	    }
517	}
