2:export class PersonClaims {
3:  private readonly sheets = inject(Sheets);
4:  protected readonly session = inject(Session);
5:  private readonly api = inject(Claims);
7:  readonly personId = input.required<number>();
8:  readonly personName = input.required<string>();
9:  /** This person's claims, newest first. */
10:  readonly claims = input.required<ClaimView[]>();
11:  /** The rates of each grade, in the order they take effect. */
12:  readonly ratesByGrade = input.required<ReadonlyMap<Grade, RateLine>>();
13:  /** This person's grades: a claim is at the one in force on its date. */
14:  readonly grades = input.required<Pick<PersonView, 'grade' | 'grades'>>();
15:  /** The sheet's periods, by from-date. */
16:  readonly periods = input.required<readonly PeriodView[]>();
17:  /** The other people on the sheet a claim can be moved to. */
18:  readonly others = input<readonly Pick<PersonView, 'id' | 'name'>[]>([]);
19:  /** The person's holds: they no longer take any claim out of a total; only the pools' cuts heed them. */
20:  readonly holds = input<readonly HoldView[]>([]);
21:  /** The person's retirement date (null: not retired): once the sheet's today reaches it, their open claims not
22:   *  bound by a statement count in no total. */
23:  readonly retiredFrom = input<string | null>(null);
24:  /** The ids of the claims selected for a bulk action. */
25:  readonly selected = input<ReadonlySet<number>>(new Set());
26:  readonly saved = output<ClaimView>();
27:  readonly selectToggled = output<{ id: number; selected: boolean }>();
29:  protected readonly notAvailable = NOT_AVAILABLE;
30:  protected readonly claimed = computed(() => money(this.claims().filter(countsClaimed(this.sheets.current()?.today ?? '', this.retiredFrom())).filter((c) => c.corrects === null).reduce((sum, c) => sum + cents(c.amount), 0)));
31:  protected readonly editingId = signal<number | null>(null);
32:  /** Whether the form was typed into since the edit button was pressed. */
33:  private typedSinceEdit = false;
34:  protected readonly error = signal<string | null>(null);
35:  protected readonly saving = signal(false);
36:  /** The error of the last action taken on a claim's row, until the next action on that row. */
37:  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
38:  /** The line typed for each claim, by id. */
39:  protected readonly lineDrafts = signal<Readonly<Record<number, { label: string; qty: string; unit: string }>>>({});
40:  /** The audit lines shown as each claim's timeline, by id. */
41:  protected readonly timelines = signal<Readonly<Record<number, readonly string[]>>>({});
42:  /** The comment typed for each claim, by id. */
43:  protected readonly commentTexts = signal<Readonly<Record<number, string>>>({});
