              statements: this.statementsApi.list(sheet.id),
              snapshots: this.snapshotsApi.list(sheet.id),
              patrons: this.patronsApi.list(sheet.id),
              watched: this.watchesApi.list(sheet.id),
              plans: this.plansApi.load(sheet.id),
              descendants: this.consolidatedApi.descendants(sheet.id),
            })
          : of({ people: [], claims: [], statements: [], snapshots: [], patrons: [], watched: [], plans: [], descendants: NO_DESCENDANTS });
      }),
      takeUntilDestroyed(),
    )
    .subscribe({
      next: ({ people, claims, statements, snapshots, patrons, watched, descendants }) => {
        this.descendants.set(descendants);
        this.patrons.set(patrons);
        this.watched.set(new Set(watched));
        this.people.set(people);
        this.claims.set(claims);
        this.statements.set(new Map(statements.map((s) => [s.personId, s])));
        this.snapshots.set(byPerson(snapshots));
        this.sheetLoaded.set(true);
      },
    });
  // An error is removed as soon as its form is changed.
  this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  this.quickForm.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.quickError.set(null));
  this.pasteForm.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.pasteError.set(null));
  this.importForm.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.importError.set(null));
}

/** The statuses each person's row counts their claims in, in the order it lists them. */
protected readonly PERSON_COUNT_STATUSES = ['OPEN', 'SETTLED'] as const;
/** Per person: how many of their claims are in each status. */
private readonly statusCountsByPerson = computed(() =>
  new Map(this.people().map((p) => {
    const counts = new Map<string, number>();
    for (const c of this.claimsOf(p.id)) counts.set(c.status, (counts.get(c.status) ?? 0) + 1);
    return [p.id, counts];
  })));
/** How many of a person's claims are in a status. */
protected statusCountOf(personId: number, status: string): number {
  return this.statusCountsByPerson().get(personId)?.get(status) ?? 0;
}

protected claimsOf(personId: number): ClaimView[] {
  return this.claimsByPerson().get(personId) ?? NO_CLAIMS;
}

/** The person's name as the screen shows it: with their grade in force on the sheet's today. */
protected nameShown(p: PersonView): string {
  return nameWithGrade(p, this.todayNow());
}

/** The person's grade in force on the sheet's today. */
protected gradeToday(p: PersonView): Grade {
  return gradeOn(p, this.sheets.current()?.today ?? '');
}

/** What a claim's own person counts of its due, in whole cents: the due less its holders' parts (one with no rate
 *  taking 0.00). */
private ownPart(c: ClaimView, due: number, dueTerms: DueTerms): number {
  return (c.shares ?? []).reduce((rest, sh) => rest - (this.holderPart(c, sh, due, dueTerms) ?? 0), due);
}

/** A holder's part of a claim with this due, in whole cents: a settled claim keeps its parts frozen, its settled
 *  due times the holder's share divided by 100, rounded half to even; any other claim's is its amount times the
 *  share divided by 100, times the rate of the holder's own grade in force on the claim's date divided by 100,
 *  rounded as the claim rounds; null when their grade has no rate then. */
private holderPart(c: ClaimView, sh: { personId: number; share: string }, due: number, dueTerms: DueTerms): number | null {
  if (c.settledDue !== null) return sharePartCents(due, sh.share);
  const holder = this.people().find((p) => p.id === sh.personId);
  if (!holder) return null;
  const rate = rateOnLine(this.rates.lineByGrade().get(gradeOn(holder, c.date)) ?? NO_RATES, c.date, c.id);
  if (rate === undefined) return null;
  return holderPartCents(cents(c.amount), sh.share, rate, roundsHalfUp(roundingDate(c, this.claimsOf(c.personId)), dueTerms));
}

/** A claim's due in whole cents, at the rates of its person's grade in force on its date; null with none. */
private claimDue(p: PersonView, c: ClaimView, dueTerms: DueTerms): number | null {
  const grade = gradeOn(p, c.date);
  return claimDueCents(c, this.rates.lineByGrade().get(grade) ?? NO_RATES, dueTerms,
    roundingDate(c, this.claimsOf(p.id)), grade);
}

protected sortBy(key: string): void {
  if (!(SORT_KEYS as readonly string[]).includes(key)) return;
  const user = this.session.user()?.trim().toLowerCase() ?? '';
  this.sortByUser.update((m) => new Map(m).set(user, key as SortKey));
}

